<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $users = DB::table("employee_payroll")->join("project_employee", "employee_payroll.p_id", "=", "project_employee.p_id")->select("employee_payroll.*", "project_employee.name")->where("project_employee.name", "like", "%ajay%")->orderBy("employee_payroll.id", "desc")->get(); file_put_contents("tmp_ajay.json", json_encode($users, JSON_PRETTY_PRINT));
